using System;namespace Recovered.Gameplay {public static class PtlProgramTokens {public static uint Create(SoundSetupImage m,uint manager,uint runtime,uint material,uint mode,uint fourth,uint fifth,Func<SoundSetupImage,uint,uint[],uint> external){return Observe(m,manager,runtime,material,mode,fourth,fifth,external,null);}public static uint Observe(SoundSetupImage m,uint manager,uint runtime,uint material,uint mode,uint fourth,uint fifth,Func<SoundSetupImage,uint,uint[],uint> external,Action<uint> tokenObserver){return PtlProgramCache.Create(m,manager,runtime,material,mode,fourth,fifth,delegate(SoundSetupImage image,uint address,uint[] values){if(address!=0x744b70)return external(image,address,values);uint[] key=new uint[9];Array.Copy(values,key,9);uint token=PtlTokenDescriptor.Values(image,key,values[9],external);if(tokenObserver!=null)tokenObserver(token);return token;});}}}
